 return <><button className="back" onClick={()=>onNavigate('Overview')}><ArrowLeft size={17}/>Back to overview</button><PageIntro eyebrow="CEFR SKILL PROFILE" title={record.learner.name+'’s full proficiency report'} text="Review evidence for each communication skill and plan the next assessment."/><section className="report-summary"><div><span className="eyebrow">SPANISH · FOUR SKILLS</span><h2>Assessment needed</h2><p>Saved grammar exercises do not establish an overall CEFR level.</p></div><Award size={42}/></section><div className="report-cards">{Object.keys(descriptions).map(name=><button className={'report-card '+(selected===name?'active':'')} key={name} aria-pressed={selected===name} onClick={()=>setSelected(name)}><b>{name}</b><strong>—</strong><small>Not assessed</small></button>)}</div><section className="report-detail" aria-live="polite"><span className="eyebrow">{selected.toUpperCase()} · CEFR</span><h2>{selected}</h2><p>{descriptions[selected]}</p><p>No assessed sample is available for this skill. Record a class observation to build the learner’s evidence.</p><button className="primary" onClick={()=>onNavigate('Class notes')}>Record an observation <ChevronRight size={16}/></button></section></>;
