function ConnectedTeacher({section='Overview',onNavigate}){
 const [learners,setLearners]=useState([]),[selected,setSelected]=useState(''),[record,setRecord]=useState(null),[notes,setNotes]=useState([]),[code,setCode]=useState(''),[focus,setFocus]=useState('Subjunctive'),[note,setNote]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const refresh=async()=>{const r=await api('/teacher/learners');setLearners(r.learners);setSelected(id=>id&&r.learners.some(x=>x.id===id)?id:r.learners[0]?.id||'')};
 useEffect(()=>{refresh().catch(e=>setError(e.message))},[]);
 useEffect(()=>{if(!selected){setRecord(null);setNotes([]);return}let live=true;setRecord(null);setNotes([]);Promise.all([api('/teacher/learners/'+selected),api('/teacher/learners/'+selected+'/notes')]).then(([a,b])=>{if(live){setRecord(a);setNotes(b.notes)}}).catch(e=>{if(live)setError(e.message)});return()=>{live=false}},[selected]);
 useEffect(()=>{if(!selected)return;const timer=setInterval(()=>api('/teacher/learners/'+selected).then(setRecord).catch(()=>{}),15000);return()=>clearInterval(timer)},[selected]);
 const connect=async e=>{e.preventDefault();setError('');try{await api('/teacher/connect',{method:'POST',body:JSON.stringify({code})});setCode('');setMessage('Learner connected.');await refresh()}catch(err){setError(err.message)}};
 const save=async e=>{e.preventDefault();if(!selected||saving)return;setError('');setSaving(true);try{const r=await api('/teacher/learners/'+selected+'/notes',{method:'POST',body:JSON.stringify({focus,note})});setNotes(list=>[{...r.note,teacher:'You'},...list]);setNote('');setMessage('Class note saved to this learner’s account.')}catch(err){setError(err.message)}finally{setSaving(false)}};
 return <>{message&&<p className="auth-success" role="status">{message}</p>}{error&&<p className="auth-error" role="alert">{error}</p>}
 {section==='Overview'&&<section className="panel connect-code"><div><h2>Connect a learner</h2><p>Ask the learner to generate a one-time code in Account.</p></div><form onSubmit={connect}><input aria-label="Learner sharing code" value={code} onChange={e=>setCode(e.target.value.toUpperCase())} placeholder="12-character code" maxLength={12} required/><button className="primary">Connect</button></form></section>}
 {learners.length===0?<><PageIntro eyebrow="CONNECTED TEACHER VIEW" title="Your learners" text="Connect a learner to see their saved results and record class observations."/><section className="panel empty-learner"><Users size={25}/><h2>No learners connected yet</h2><p>Enter a sharing code on Overview after your learner creates one in Account.</p>{section!=='Overview'&&<button className="primary" onClick={()=>onNavigate('Overview')}>Go to Overview</button>}</section></>:<>
 <div className="learner-picker"><label htmlFor="choose-learner">Viewing learner</label><select id="choose-learner" disabled={saving} value={selected} onChange={e=>{setMessage('');setError('');setNote('');setFocus('Subjunctive');setSelected(e.target.value)}}>{learners.map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></div>
 {record?.sharing?.selfLearning===false&&<div className="privacy-banner"><Users size={18}/><div><b>Self-study activity is private</b><p>This learner has hidden lesson activity, attempts and scores. Class notes and your connection are still available.</p></div></div>}
 {!record?<section className="panel account-loading">Loading learner record…</section>:section==='Full report'?<TeacherReportLive record={record} onNavigate={onNavigate}/>:section==='Assignments'?<TeacherAssignmentLive key={selected} record={record} notes={notes} onSave={async(focus,note)=>{const r=await api('/teacher/learners/'+selected+'/notes',{method:'POST',body:JSON.stringify({focus,note})});setNotes(list=>[{...r.note,teacher:'You'},...list])}}/>:section==='Learning memory'?<TeacherMemoryLive key={selected} record={record} notes={notes} onNavigate={onNavigate}/>:section==='Class notes'?<TeacherNotesLive record={record} notes={notes} focus={focus} setFocus={setFocus} note={note} setNote={setNote} onSave={save} onNavigate={onNavigate} saving={saving}/>:<TeacherOverviewLive record={record} notes={notes} onNavigate={onNavigate}/>} 
 </>}</>;
}

function App(){
 const [role,setRole]=useState('learner'),[tab,setTab]=useState('Overview'),[activeLesson,setActiveLesson]=useState(null);
 const [user,setUser]=useState(null),[authReady,setAuthReady]=useState(false),[authError,setAuthError]=useState('');
 const [deviceHistory,setDeviceHistory]=useState(loadPracticeHistory),[practiceHistory,setPracticeHistory]=useState([]),[notes,setNotes]=useState([]);
 useEffect(()=>{api('/auth/me').then(async r=>{if(r.user){setUser(r.user);setRole(r.user.role);if(r.user.role==='learner'){const [p,n]=await Promise.all([api('/practice'),api('/notes')]);setPracticeHistory(p.attempts);setNotes(n.notes)}}else setPracticeHistory(loadPracticeHistory())}).catch(e=>{setAuthError('Account service unavailable: '+e.message);setPracticeHistory(loadPracticeHistory())}).finally(()=>setAuthReady(true))},[]);
 useEffect(()=>{if(authReady&&!user){localStorage.setItem(practiceKey,JSON.stringify(practiceHistory));if(practiceHistory[0])localStorage.setItem('continuumScore',String(forLesson(practiceHistory)[0]?.score??0))}},[practiceHistory,user,authReady]);
 const teacher=user?user.role==='teacher':role==='teacher';
 const nav=user?.role==='teacher'?['Overview','Learning memory','Class notes','Assignments','Account']:teacher?['Overview','Learning memory','Class notes','Assignments','Account']:['Overview','Learn','My classes','Learning memory','Account'];
 const icons={'Overview':LayoutDashboard,'Learn':BookOpen,'My classes':CalendarDays,'Learning memory':NotebookPen,'Class notes':NotebookPen,'Assignments':Target,'Account':Users};
 const navigate=n=>{setTab(n);setActiveLesson(null);window.scrollTo({top:0,behavior:'smooth'})};
 const start=id=>{setTab('Learn');setActiveLesson(id);window.scrollTo({top:0,behavior:'smooth'})};
 const completePractice=async result=>{if(user){const r=await api('/practice',{method:'POST',body:JSON.stringify({lesson:result.lesson,answers:result.answers,submissionKey:result.submissionKey})});setPracticeHistory(history=>[r.attempt,...history.filter(a=>a.id!==r.attempt.id)]);return r.attempt}const history=[result,...practiceHistory];localStorage.setItem(practiceKey,JSON.stringify(history));setPracticeHistory(history);return result};
 const signedIn=async person=>{setUser(person);setRole(person.role);setAuthError('');setTab('Account');if(person.role==='learner'){const [p,n]=await Promise.all([api('/practice'),api('/notes')]);setPracticeHistory(p.attempts);setNotes(n.notes)}else{setPracticeHistory([]);setNotes([])}};
 const signedOut=async()=>{try{await api('/auth/logout',{method:'POST'});setUser(null);setRole('learner');setPracticeHistory(loadPracticeHistory());setNotes([]);navigate('Overview')}catch(e){setAuthError(e.message)}};
 const importProgress=async()=>{await api('/practice/import',{method:'POST',body:JSON.stringify({attempts:deviceHistory.map(({score,total,at,lesson})=>({score,total,at,lesson}))})});const r=await api('/practice');setPracticeHistory(r.attempts);setDeviceHistory([])};
 const latest=forLesson(practiceHistory)[0],patterns=issues.map(i=>i.name==='Subjunctive'&&latest?{...i,score:latest.score,status:latest.source==='imported'?'Imported practice':'Latest practice'}:i);
 let page;
 if(!authReady)page=<section className="panel account-loading">Connecting to your account…</section>;
 else if(tab==='Account')page=<Account user={user} onLogin={signedIn} onLogout={signedOut} deviceHistory={user?.role==='learner'&&!practiceHistory.length?deviceHistory:[]} onImport={importProgress} onOpenTeacher={()=>navigate('Overview')}/>;
 else if(user?.role==='teacher')page=<ConnectedTeacher section={tab} onNavigate={navigate}/>;
 else if(user?.role==='learner'&&tab==='Overview')page=<LearnerOverview user={user} attempts={practiceHistory} notes={notes} onPractice={start} onNavigate={navigate}/>;
 else if(user?.role==='learner'&&tab==='Learning memory')page=<LearnerMemory attempts={practiceHistory} notes={notes} onPractice={start} onNavigate={navigate}/>;
 else if(user?.role==='learner'&&tab==='My classes')page=<><PageIntro eyebrow="COMING NEXT" title="Classes" text="Live booking and payments are not connected yet. You can share your learning record with a teacher from Account."/><button className="primary" onClick={()=>navigate('Account')}>Connect a teacher <ChevronRight size={16}/></button></>;
 else if(tab==='Overview')page=<Overview teacher={teacher} onPractice={()=>start('subjunctive')} onNavigate={navigate} patterns={patterns} practiceHistory={practiceHistory}/>;
 else if(tab==='Full report')page=<FullReport teacher={teacher} onBack={()=>navigate('Overview')} onHistory={()=>navigate('Learning memory')} onPractice={start} practiceHistory={practiceHistory}/>;
 else if(teacher&&tab==='Learning memory')page=<TeacherMemory onAssign={()=>navigate('Assignments')} patterns={patterns} practiceHistory={practiceHistory}/>;
 else if(teacher&&tab==='Class notes')page=<ClassNotes onAssign={()=>navigate('Assignments')}/>;
 else if(teacher&&tab==='Assignments')page=<Assignments/>;
 else if(tab==='Learn')page=<SelfStudy key={user?.id||'guest'} user={user} attempts={practiceHistory} notes={notes} activeLesson={activeLesson} onStart={start} onExit={()=>setActiveLesson(null)} onComplete={completePractice}/>;
 else if(tab==='My classes')page=<Classes/>;
 else if(tab==='Learning memory')page=<Memory patterns={patterns} practiceHistory={practiceHistory} onPractice={start}/>;
 else page=<Overview teacher={teacher} onPractice={()=>start('subjunctive')} onNavigate={navigate} patterns={patterns} practiceHistory={practiceHistory}/>;
 return <div className="app"><aside><div className="brand"><div className="logo">C</div><span>Continuum<small>LEARN WITHOUT RESETTING</small></span></div><nav>{nav.map(n=>{const Icon=icons[n];return <button className={tab===n||tab==='Full report'&&n==='Overview'?'active':''} onClick={()=>navigate(n)} key={n}><Icon size={19}/>{n}</button>})}</nav><div className="side-card"><Sparkles size={20}/><b>{user?'Your record is saved':teacher?'AI class copilot':'Your memory travels'}</b><p>{user?'Practice follows your account. Share access only with teachers you choose.':teacher?'Preview how class patterns turn into practice.':'Preview the app, then create an account to keep your progress.'}</p></div><div className="profile" onClick={()=>navigate('Account')} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&navigate('Account')}><div className="avatar">{user?user.name.slice(0,2).toUpperCase():'KI'}</div><span><b>{user?.name||'Ken Ishizawa'}</b><small>{user?user.role:'Preview · Spanish B1+'}</small></span><ChevronRight size={17}/></div></aside>
 <main><header><div className="mobile-brand">Continuum</div><div className="search"><Search size={18}/><span>{user?'Your saved learning record':'Preview lessons and skills'}</span></div><div className="role">{user?<button className="on" onClick={()=>navigate('Account')}>{user.role==='teacher'?'Teacher account':'Learner account'}</button>:<><button className={!teacher?'on':''} onClick={()=>{setRole('learner');navigate('Overview')}}>Learner</button><button className={teacher?'on':''} onClick={()=>{setRole('teacher');navigate('Overview')}}>Teacher</button></>}</div></header><div className="content">{authError&&<p className="auth-error" role="alert">{authError}</p>}{page}</div><nav className="mobile-nav" style={{gridTemplateColumns:`repeat(${nav.length},1fr)`}}>{nav.map(n=>{const Icon=icons[n];return <button className={tab===n?'active':''} onClick={()=>navigate(n)} key={n}><Icon size={19}/><span>{n==='Learning memory'?'Memory':n==='Class notes'?'Notes':n==='My classes'?'Classes':n}</span></button>})}</nav></main></div>
}
createRoot(document.getElementById('root')).render(<App/>);
